typedef unsigned int size_t;

struct FEMenuEntry { int entry_num; };

class FEManager {
    char padding[0x15660];
public:
    bool score_display;
    void enableScoreDisplay(bool on) { score_display = on; }
};

class FEGraphicalMenu {
    char padding[0x13c];
public:
    FEManager *manager;
};

class FEMenu {
public:
    void play_sound(const char *name);
};

class rumbleManager {
public:
    void turnOn(bool on, int controller);
};

extern rumbleManager rumbleMan;

enum _nslSpeakerModeEnum {
    NSL_SPEAKER_STEREO = 0,
    NSL_SPEAKER_MONO = 1,
    NSL_SPEAKER_PROLOGIC = 3
};
void nslSetSpeakerMode(_nslSpeakerModeEnum mode);

class OptionsMenu : public FEMenu {
    char padding0[0x48];
    FEMenuEntry *highlighted;
    char padding1[0x14];
    FEGraphicalMenu *parent;
    char padding2[0x1f0];
    int stereo_op;
    char padding3[0x7c];
    bool switches[5];
public:
    enum { OpScoreEntry, OpRumble1Entry, OpRumble2Entry, OpRumble3Entry,
           OpRumble4Entry, OpStereoEntry, OpMasterEntry };
    void RumbleOn(bool on, int controller);
    void ChangeSwitch(bool up);
};

void OptionsMenu::ChangeSwitch(bool up)
{
	int index = highlighted->entry_num;

	if(index == OpStereoEntry)
	{
		if(up)
		{
			stereo_op++;
			if(stereo_op == 3) stereo_op = 0;
		}
		else
		{
			stereo_op--;
			if(stereo_op == -1) stereo_op = 2;
		}
	}
	else switches[index] = !switches[index];

	play_sound("LEFTRIGHT");

	switch(index)
	{
	case OpScoreEntry:   ((FEGraphicalMenu*)parent)->manager->enableScoreDisplay(switches[index]); break;
	case OpStereoEntry:
		if(stereo_op == 0) nslSetSpeakerMode(NSL_SPEAKER_MONO);
		else if(stereo_op == 1) nslSetSpeakerMode(NSL_SPEAKER_STEREO);
		else nslSetSpeakerMode(NSL_SPEAKER_PROLOGIC); break;
	case OpRumble1Entry: RumbleOn(switches[index], 0);  rumbleMan.turnOn(switches[index], 0); break;
	case OpRumble2Entry: RumbleOn(switches[index], 1);  rumbleMan.turnOn(switches[index], 1); break;
	case OpRumble3Entry: RumbleOn(switches[index], 2);  rumbleMan.turnOn(switches[index], 2); break;
	case OpRumble4Entry: RumbleOn(switches[index], 3);  rumbleMan.turnOn(switches[index], 3); break;
	default: __builtin_trap();
	}
}
